struct CoarseConfig {
    uint tile_count;
    uint tiles_width;
    uint tiles_height;
    uint draw_start;
    uint draw_end;
    uint layer_stack_start;
    uint layer_stack_end;
    uint ptcl_capacity;
    uint glyph_capacity;
    uint chunk_count;
    uint text_run_count;
    uint text_glyph_count;
    uint tile_draw_index_count;
    uint emit_chunk_capacity;
    uint paint_brush_base;
    uint text_enabled;
    uint active_tile_count;
    uint active_tile_list_base;
    uint incremental;
};
ConstantBuffer<CoarseConfig> config : register(b0, space0);

sources.coarse/emit_allocation.hlsl:
#include "config.hlsli"
RWByteAddressBuffer coarse_work : register(u7, space0);
RWByteAddressBuffer chunk_records : register(u8, space0);
#include "prefix_scan.hlsli"
#include "emit_layout.hlsli"

[numthreads(COARSE_WORKGROUP_SIZE, 1, 1)]
void coarse_emit_chunk_counts(uint3 id : SV_DispatchThreadID) {
    if (id.x >= config.tile_count) return;
    uint count = coarse_work.Load(tile_draw_base(id.x) + COARSE_TILE_DRAW_COUNT);
    coarse_work.Store(tile_emit_base(id.x), (count + COARSE_WORKGROUP_SIZE - 1u) / COARSE_WORKGROUP_SIZE);
}

[numthreads(COARSE_WORKGROUP_SIZE, 1, 1)]
void coarse_emit_prefix_chunks(uint3 group : SV_GroupID, uint3 local : SV_GroupThreadID) {
    if (group.x >= config.chunk_count) return;
    uint tile = group.x * COARSE_WORKGROUP_SIZE + local.x;
    uint count = 0u;
    if (tile < config.tile_count) count = coarse_work.Load(tile_emit_base(tile));
    uint2 offset = exclusive_prefix(uint2(count, 0u), local.x);
    if (local.x == 0u) chunk_records.Store(group.x * COARSE_CHUNK_RECORD_STRIDE, block_total.x);
    if (tile < config.tile_count) coarse_work.Store(tile_emit_base(tile) + 4u, offset.x);
}

[numthreads(1, 1, 1)]
void coarse_emit_chunk_offsets() {
    uint carry = 0u;
    for (uint chunk = 0u; chunk < config.chunk_count; chunk++) {
        uint base = chunk * COARSE_CHUNK_RECORD_STRIDE;
        chunk_records.Store(base + COARSE_CHUNK_PTCL_OFFSET, carry);
        carry += chunk_records.Load(base);
    }
}

[numthreads(COARSE_WORKGROUP_SIZE, 1, 1)]
void coarse_emit_apply_chunk_offsets(uint3 id : SV_DispatchThreadID) {
    if (id.x >= config.tile_count) return;
    uint base = tile_emit_base(id.x) + 4u;
    uint chunk_base = (id.x / COARSE_WORKGROUP_SIZE) * COARSE_CHUNK_RECORD_STRIDE;
    coarse_work.Store(base, coarse_work.Load(base) + chunk_records.Load(chunk_base + COARSE_CHUNK_PTCL_OFFSET));
}

[numthreads(COARSE_WORKGROUP_SIZE, 1, 1)]
void coarse_emit_fill_refs(uint3 id : SV_DispatchThreadID) {
    if (id.x >= config.tile_count) return;
    uint2 record = coarse_work.Load2(tile_emit_base(id.x));
    for (uint local = 0u; local < record.x; local++) {
        uint reference = record.y + local;
        if (reference < config.emit_chunk_capacity) {
            uint base = emit_base(reference);
            coarse_work.Store2(base, uint2(id.x, local));
            coarse_work.Store(base + COARSE_EMIT_CLASS_FLAGS, 0u);
        }
    }
}

sources.coarse/emit_layout.hlsli:
// Byte offsets through the packed coarse work buffer; preceding regions remain intact.
uint tile_draw_base(uint tile) {
    return config.tile_count * COARSE_TILE_RECORD_STRIDE + config.ptcl_capacity * COARSE_PTCL_RECORD_STRIDE +
        config.glyph_capacity * 4u + tile * COARSE_TILE_DRAW_RECORD_STRIDE;
}
uint tile_emit_base(uint tile) {
    return tile_draw_base(config.tile_count) + config.tile_draw_index_count * 4u + tile * COARSE_TILE_EMIT_RECORD_STRIDE;
}
uint emit_base(uint reference) {
    return tile_emit_base(config.tile_count) + reference * COARSE_EMIT_RECORD_STRIDE;
}

sources.coarse/prefix_scan.hlsli:
// Particle and glyph allocation use the same ordered, wrapping-u32 scan.
groupshared uint2 scratch[COARSE_WORKGROUP_SIZE];
groupshared uint2 block_total;

uint2 exclusive_prefix(uint2 value, uint lane) {
    scratch[lane] = value;
    GroupMemoryBarrierWithGroupSync();
    for (uint step = 1u; step < COARSE_WORKGROUP_SIZE; step *= 2u) {
        uint index = (lane + 1u) * step * 2u - 1u;
        if (index < COARSE_WORKGROUP_SIZE) scratch[index] += scratch[index - step];
        GroupMemoryBarrierWithGroupSync();
    }
    if (lane == 0u) {
        block_total = scratch[COARSE_WORKGROUP_SIZE - 1u];
        scratch[COARSE_WORKGROUP_SIZE - 1u] = uint2(0u, 0u);
    }
    GroupMemoryBarrierWithGroupSync();
    for (uint step = COARSE_WORKGROUP_SIZE / 2u; step > 0u; step /= 2u) {
        uint index = (lane + 1u) * step * 2u - 1u;
        if (index < COARSE_WORKGROUP_SIZE) {
            uint left = index - step;
            uint2 previous = scratch[left];
            scratch[left] = scratch[index];
            scratch[index] += previous;
        }
        GroupMemoryBarrierWithGroupSync();
    }
    uint2 result = scratch[lane];
    GroupMemoryBarrierWithGroupSync();
    return result;
}

