groupshared uint2 scratch[COARSE_WORKGROUP_SIZE];
groupshared uint2 block_total;

uint2 exclusive_prefix(uint2 value, uint lane) {
    scratch[lane] = value;
    GroupMemoryBarrierWithGroupSync();
