            uint2 previous = scratch[left];
            scratch[left] = scratch[index];
            scratch[index] += previous;
        }
        GroupMemoryBarrierWithGroupSync();
    }
    uint2 result = scratch[lane];
    GroupMemoryBarrierWithGroupSync();
    return result;
}

